=Analisa os dados deste candidato a mentoria de carreira em TI para a sessão diagnóstica com Alex Seles:
Nome: {{ $('Webhook Site (Mafalda)').item.json.body.nome }}
Objetivo: {{ $('Webhook Site (Mafalda)').item.json.body.objetivo }}
Desafio / Dor: {{ $('Webhook Site (Mafalda)').item.json.body.desafio }}
Telemóvel: {{ $('Webhook Site (Mafalda)').item.json.body.telefone }}

Gera um Dossiê Executivo conciso em Português de Portugal com:
1. Classificação do Perfil (Júnior, Pleno, Sénior, Transição ou Liderança)
2. Diagnóstico da Dor Central
3. 3 Perguntas Estratégicas para o Alex Seles fazer na videochamada
4. Trilha de Mentoria Recomendada (PMP, Scrum, SAFe, ITIL ou Transição)

parameters.jsCode:
// 1. Obtém os dados do Webhook com o nome exato do nó (sem o 1)
const webhookNode = $('Webhook Site (Mafalda)');
const webhookData = (webhookNode.first() && webhookNode.first().json.body) 
  ? webhookNode.first().json.body 
  : (webhookNode.item && webhookNode.item.json.body) 
  ? webhookNode.item.json.body 
  : {};
// 2. Extrai o Dossiê Executivo da IA (formato LangChain OpenAI v2.1)
const aiItem = $input.item.json;
const aiOutput = 
  aiItem.output?.[0]?.content?.[0]?.text ||
  aiItem.message?.content ||
  aiItem.text ||
  'Dossiê gerado com sucesso.';
// 3. Normalização de dados (com blindagem para o Google Sheets não dar #ERROR!)
const nome = webhookData.nome || 'Candidato';
const email = webhookData.email || 'alexseles40@gmail.com';
let rawTelefone = webhookData.telefone || 'Não informado';
// Se começar com '+', adiciona apóstrofo para o Google Sheets tratar como texto e não dar #ERROR!
const telefone = (typeof rawTelefone === 'string' && rawTelefone.startsWith('+'))
  ? "'" + rawTelefone
  : rawTelefone;
const cidade = webhookData.cidade || 'Não informado';
const tipoSolicitacao = webhookData.tipoSolicitacao || 'Sessão Diagnóstica';
const modulo = webhookData.modulo || 'Sessão Diagnóstica Geral (30 min)';
const investimento = webhookData.investimento || (tipoSolicitacao === 'Contratação de Módulo' ? 'Sob Consulta' : 'Sessão Inicial');
const horas = webhookData.horas || '30 Minutos';
const objetivo = webhookData.objetivo || (tipoSolicitacao === 'Contratação de Módulo' ? `Contratação: ${modulo}` : 'Mentoria Executiva em TI');
const desafio = webhookData.desafio || 'Não informado';
const slotAgendamento = webhookData.slotAgendamento || (tipoSolicitacao === 'Contratação de Módulo' ? 'A combinar após alinhamento' : 'Sessão Diagnóstica');
const canal = webhookData.canal || 'Formulário do Site';
const startISO = webhookData.startISO || new Date().toISOString();
const endISO = webhookData.endISO || new Date(Date.now() + 30 * 60 * 1000).toISOString();
const isModulo = tipoSolicitacao === 'Contratação de Módulo';
const calendarSummary = isModulo ? `[CONTRATAÇÃO: ${investimento}] ${nome} • ${modulo}` : `Sessão Diagnóstica: ${nome} com Alex Seles`;
const calendarDescription = [
  `SOLICITAÇÃO: ${tipoSolicitacao.toUpperCase()}`,
  `MÓDULO / PROGRAMA: ${modulo}`,
  `INVESTIMENTO: ${investimento}`,
  `CARGA HORÁRIA: ${horas}`,
  `CANAL: ${canal}`,
  `------------------------------------------------------------`,
  `CANDIDATO: ${nome}`,
  `CIDADE / PAÍS: ${cidade}`,
  `OBJETIVO: ${objetivo}`,
  `MAIOR DESAFIO: ${desafio}`,
  `TELEMOVEL: ${rawTelefone}`,
  `E-MAIL: ${email}`,
  `HORÁRIO / AGENDA: ${slotAgendamento}`,
  `LOCAL: Google Meet`,
  ``,
  `--- DOSSIÊ ESTRATÉGICO GERADO PELA IA (GPT-4o-mini) ---`,
  aiOutput,
  ``,
  `------------------------------------------------------------`,
  `MENTOR: Alex Seles | alexseles40@gmail.com | +351 912 405 814`
].join('\n');
return [{
  json: {
    nome,
    email,
    telefone,
    cidade,
    tipoSolicitacao,
    modulo,
    investimento,
    horas,
    objetivo,
    desafio,
    slotAgendamento,
    canal,
    startISO,
    endISO,
    aiDossie: aiOutput,
    calendarSummary,
    calendarDescription,
    dataRegisto: new Date().toLocaleString('pt-PT', { timeZone: 'Europe/Lisbon' })
  }
}];

let lead;
try {
  lead = $('Formatar Dados & Dossiê1').item.json;
} catch (e) {
  lead = $input.item.json;
}

const isModulo = (lead.tipoSolicitacao || lead['Tipo Solicitação']) === 'Contratação de Módulo';
const nome = lead.nome || lead.Nome || 'Candidato';
const modulo = lead.modulo || lead['Módulo / Programa'] || 'Sessão Diagnóstica';
const investimento = lead.investimento || lead.Investimento || (isModulo ? 'Sob Consulta' : 'Sem Custo Direto');
const horas = lead.horas || lead['Carga Horária'] || '30 Minutos';
const objetivo = lead.objetivo || lead.Objetivo || (isModulo ? `Contratação: ${modulo}` : 'Mentoria Executiva em TI');
const desafio = lead.desafio || lead.Desafio || 'Não informado';
const telefone = lead.telefone || lead.Telemóvel || 'Não informado';
const email = lead.email || lead['E-mail'] || 'alexseles40@gmail.com';
const cidade = lead.cidade || lead.Cidade || 'Não informado';
const slotAgendamento = lead.slotAgendamento || lead['Reunião Agendada'] || 'A combinar';
const canal = lead.canal || lead.Canal || 'Formulário do Site';
const dataRegisto = lead.dataRegisto || lead.Data || new Date().toLocaleString('pt-PT', { timeZone: 'Europe/Lisbon' });
const aiDossie = lead.aiDossie || lead.Notas || 'Dossiê processado.';

const cardTitle = isModulo ? `[${investimento}] ${nome} • ${modulo}` : `[Sessão Diagnóstica] ${nome} • ${objetivo}`;

const cardDescription = [
  `TIPO DE SOLICITAÇÃO: ${isModulo ? 'CONTRATAÇÃO DE MÓDULO' : 'SESSÃO DIAGNÓSTICA'}`,
  `MÓDULO / PROGRAMA: ${modulo}`,
  `INVESTIMENTO PREVISTO: ${investimento}`,
  `CARGA HORÁRIA: ${horas}`,
  `CANAL DE ENTRADA: ${canal}`,
  `--------------------------------------------------`,
  `DADOS DO MENTORADO:`,
  `Nome: ${nome}`,
  `Telemóvel: ${telefone}`,
  `E-mail: ${email}`,
  `Cidade / País: ${cidade}`,
  `Horário / Sessão: ${slotAgendamento}`,
  `Data de Registo: ${dataRegisto}`,
  ``,
  `OBJETIVO REGISTADO:`,
  objetivo,
  ``,
  `SITUAÇÃO / DESAFIO APRESENTADO:`,
  desafio,
  ``,
  `--- DOSSIÊ ESTRATÉGICO GERADO PELA IA ---`,
  aiDossie,
  ``,
  `--- CHECKLIST DO PLANO DE AÇÃO ---`,
  isModulo ? `[ ] Enviar proposta executiva e contrato do módulo (${investimento})` : `[ ] Realizar Sessão Diagnóstica de 30 min`,
  `[ ] Validar disponibilidade de agenda e calendário de encontros`,
  `[ ] Alinhar metas de carreira 3/6/12 meses`,
  `[ ] Revisão profunda de Perfil LinkedIn ATS e Currículo`,
  `[ ] Roteiro prático e exercícios do módulo (${modulo})`,
  `[ ] Simulação de entrevistas executivas e negociação salarial`
].join('\n');

return [{
  json: {
    cardTitle,
    cardDescription,
    lead
  }
}];
